import { isAdminRequest } from "./lib/adminAuth.js";
import { getAttendanceConfig, saveAttendanceConfig } from "./lib/configStore.js";
import { badRequest, json, methodNotAllowed, readJson, serverError, unauthorized } from "./lib/http.js";
import { getDb } from "./lib/firebaseAdmin.js";

export const handler = async (event) => {
  try {
    if (event.httpMethod === "GET") {
      const db = getDb();
      return json(200, await getAttendanceConfig(db));
    }

    if (event.httpMethod === "PUT") {
      if (!isAdminRequest(event)) {
        return unauthorized();
      }

      try {
        const db = getDb();
        const config = await saveAttendanceConfig(db, readJson(event));
        return json(200, config);
      } catch (error) {
        return badRequest(error.message || "Invalid configuration.");
      }
    }

    return methodNotAllowed();
  } catch (error) {
    return serverError(error);
  }
};
