export const DEFAULT_EMPLOYEES = [
  { id: "EMP001", name: "Veeru" },
  { id: "EMP002", name: "Raj" },
  { id: "EMP003", name: "Akash" }
];

export const DEFAULT_OFFICES = [
  {
    id: "BLR001",
    name: "Bangalore Office",
    latitude: 12.9716,
    longitude: 77.5946,
    radiusMeters: 200
  }
];

export const OFFICE_RADIUS_METERS = 200;

export async function getAttendanceConfig(db) {
  const [employeesDoc, officesDoc] = await Promise.all([
    db.collection("config").doc("employees").get(),
    db.collection("config").doc("offices").get()
  ]);

  return {
    employees: normalizeEmployees(employeesDoc.exists ? employeesDoc.data().items : DEFAULT_EMPLOYEES),
    offices: normalizeOffices(officesDoc.exists ? officesDoc.data().items : DEFAULT_OFFICES)
  };
}

export async function saveAttendanceConfig(db, config) {
  const employees = normalizeEmployees(config.employees);
  const offices = normalizeOffices(config.offices);

  if (!employees.length) {
    throw new Error("At least one employee is required.");
  }

  if (!offices.length) {
    throw new Error("At least one office is required.");
  }

  await Promise.all([
    db.collection("config").doc("employees").set({ items: employees, updatedAt: new Date() }),
    db.collection("config").doc("offices").set({ items: offices, updatedAt: new Date() })
  ]);

  return { employees, offices };
}

export function normalizeEmployees(employees = []) {
  return employees
    .map((employee) => ({
      id: normalizeId(employee.id),
      name: String(employee.name ?? "").trim()
    }))
    .filter((employee) => employee.id && employee.name);
}

export function normalizeOffices(offices = []) {
  return offices
    .map((office) => ({
      id: normalizeId(office.id),
      name: String(office.name ?? "").trim(),
      latitude: Number(office.latitude),
      longitude: Number(office.longitude),
      radiusMeters: OFFICE_RADIUS_METERS
    }))
    .filter(
      (office) =>
        office.id &&
        office.name &&
        Number.isFinite(office.latitude) &&
        office.latitude >= -90 &&
        office.latitude <= 90 &&
        Number.isFinite(office.longitude) &&
        office.longitude >= -180 &&
        office.longitude <= 180
    );
}

export function normalizeId(value) {
  return String(value ?? "").trim().toUpperCase().replace(/\s+/g, "");
}

export function findNearestOffice(offices, latitude, longitude) {
  const nearest = offices
    .map((office) => ({
      office,
      distanceMeters: distanceBetweenMeters(latitude, longitude, office.latitude, office.longitude)
    }))
    .sort((a, b) => a.distanceMeters - b.distanceMeters)[0];

  return {
    ...nearest,
    isOffice: nearest.distanceMeters <= OFFICE_RADIUS_METERS
  };
}

function distanceBetweenMeters(latA, lonA, latB, lonB) {
  const earthRadiusMeters = 6371000;
  const toRadians = (degrees) => (degrees * Math.PI) / 180;
  const dLat = toRadians(latB - latA);
  const dLon = toRadians(lonB - lonA);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRadians(latA)) *
      Math.cos(toRadians(latB)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return earthRadiusMeters * c;
}
